/**
 * The trial-end screen (sales plan A, 2026-10-24; when it opens is
 * `trialEnd.ts`). The full-screen offer's frame (`OfferPaywall.module.css`)
 * with the trial's own story: what Pro did for the learner (the server's
 * counts), the open offer with its real countdown (live h:m:s in its last
 * day on this opened surface), the plans with their honest anchors, one
 * button, a way to invite friends where invitations are offered, and
 * "Continue with Free". Putting it away asks "Why not now?" once, when an
 * offer is open to record the answer on.
 *
 * Opened only where Pro may be sold (`trialVoiced`), so never in the
 * desktop app. A dialog: focus moves in, Escape closes, focus goes back.
 */
import { useEffect, useId, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { Link } from 'react-router-dom';
import { Icon } from '@/components/ui/Icon.js';
import { pitchDays, useInviteReward } from '@/features/invite/useInviteReward.js';
import { settingsPath } from '@/features/settings/paths.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { serverNow } from '@/lib/serverClock.js';
import { Seal } from './art/Seal.js';
import { countdownView, eventStage, whenWords } from './countdown.js';
import { useTrialFacts } from './facts.js';
import { BuyButton, BuyFoot, EndedLine, LegalRow, PlanPicker } from './KeepPro.js';
import { useKeepPro } from './keepProModel.js';
import { offerCloses, openOffer, type Offer } from './offer.js';
import { sendOfferDismissed, sendOfferEvent } from './offerEvents.js';
import { sendPaywallEvent } from './paywallEvents.js';
import { badgeWords, countdownLabel, offerBadgeKind } from './planChoices.js';
import { onIOS } from './play.js';
import { PurchaseDone } from './PurchaseDone.js';
import { usePurchase } from './purchase.js';
import { receiptRows, trialLengthDays } from './receipt.js';
import { noteSellingShown } from './sellingSignals.js';
import { canBuyHere, useBilling } from './state.js';
import { runningTrial } from './trial.js';
import type { TrialEndMoment } from './trialEnd.js';
import { useAppStoreRestore } from './useAppStoreRestore.js';
import { WhyNotNow } from './WhyNotNow.js';
import kp from './KeepPro.module.css';
import pw from './OfferPaywall.module.css';
import { aroundAmount, isNight, nightStyle } from './night.js';
import { NightClosing } from './NightClosing.js';
import { useOfferWords } from './useOfferWords.js';
import styles from './TrialEndScreen.module.css';

/**
 * The offer events' surface: the server's own name for this screen, so its
 * shown, opened and dismissed counts (and "Why not now?" answers) stay apart
 * from a campaign's full-screen offer, which keeps `fullscreen`.
 */
const SURFACE = 'trial_end';

export function TrialEndScreen({
  moment,
  onClose,
}: {
  moment: TrialEndMoment;
  onClose: () => void;
}): React.JSX.Element {
  const state = useBilling((s) => s.state);
  const refresh = useBilling((s) => s.refresh);
  const purchase = usePurchase();
  const restore = useAppStoreRestore(purchase.finish);
  const [now] = useState(() => new Date(serverNow()));
  // The offer as the screen opened, kept: buying ends it on the server and
  // the screen must stay for "Pro is yours".
  const [offer] = useState(() => openOffer(state, now));
  const [ended, setEnded] = useState(false);
  const model = useKeepPro(ended ? undefined : offer);
  const facts = useTrialFacts((s) => s.facts);
  const ensureFacts = useTrialFacts((s) => s.ensure);
  // Pay or invite: where invitations are offered (where.ts), from the flag.
  const invite = useInviteReward();
  const [asking, setAsking] = useState(false);
  const titleId = useId();
  const askId = useId();
  const trustId = useId();
  const legalId = useId();
  const panel = useRef<HTMLDivElement>(null);
  const done = purchase.stage !== 'choosing' || purchase.approved;
  const running = moment.kind === 'last' ? runningTrial(state, now) : undefined;
  const look = offer?.creative?.look;
  const badge = model.choices.find((one) => one.offer !== undefined)?.badge;

  // Putting it away: once, "Why not now?" when there is an offer to record
  // the answer on; otherwise, or after buying, it simply closes.
  const leave = useRef<() => void>(() => undefined);
  useEffect(() => {
    leave.current = () => {
      if (done || offer === undefined || ended) {
        onClose();
        return;
      }
      if (asking) {
        sendOfferDismissed(offer.id, SURFACE, undefined);
        onClose();
        return;
      }
      setAsking(true);
    };
  });

  useEffect(() => {
    ensureFacts();
  }, [ensureFacts]);

  useEffect(() => {
    const restoreTo = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    panel.current?.focus();
    const onKey = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') {
        event.stopPropagation();
        leave.current();
      }
    };
    document.addEventListener('keydown', onKey);
    const overflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      document.removeEventListener('keydown', onKey);
      document.body.style.overflow = overflow;
      restoreTo?.focus();
    };
  }, []);

  useEffect(() => {
    noteSellingShown();
    sendPaywallEvent('offer_paywall', 'shown');
    // The plans are this screen, so seeing it is opening them.
    sendPaywallEvent('offer_paywall', 'opened');
    if (offer === undefined) return;
    const closes = offerCloses(offer);
    const view =
      closes === undefined
        ? undefined
        : countdownView({
            closesAt: closes,
            now: serverNow(),
            surface: 'opened',
            liveSecondsFromHours: look?.liveSecondsFromHours ?? LIVE_HOURS,
            style: look?.countdownStyle ?? 'auto',
            calm: false,
          });
    sendOfferEvent(offer.id, 'shown', SURFACE, {
      ...(view === undefined ? {} : { countdownStage: eventStage(view.stage) }),
      ...(offer.creative === undefined
        ? {}
        : { campaignId: offer.creative.campaignId, variantId: offer.creative.variantId }),
    });
    // Once per opening.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const length = trialLengthDays(facts);
  const rows = receiptRows(facts);
  const title =
    moment.kind === 'last'
      ? t('trialEnd.titleLast')
      : length === undefined
        ? t('trialEnd.titlePlain')
        : t('trialEnd.title', { count: length });
  const lead =
    moment.kind === 'last' && running !== undefined
      ? t('trialEnd.leadLast', { when: whenWords(running.endsAt, now.getTime()) })
      : t('trialEnd.leadEnded');

  return createPortal(
    <div className={pw.backdrop}>
      <div
        className={cx(pw.panel, pw.noArt)}
        role="dialog"
        aria-modal="true"
        aria-labelledby={asking ? askId : titleId}
        tabIndex={-1}
        ref={panel}
      >
        <div className={pw.side}>
          {!asking && (
            <button
              type="button"
              className={pw.close}
              aria-label={t('trialEnd.close')}
              onClick={() => {
                leave.current();
              }}
            >
              <Icon name="close" size={20} weight={2} />
            </button>
          )}
          <div className={pw.scroll}>
            {asking && offer !== undefined ? (
              <div className={cx(pw.body, styles.askBody)}>
                <WhyNotNow
                  titleId={askId}
                  onAnswer={(reason) => {
                    sendOfferDismissed(offer.id, SURFACE, reason);
                    onClose();
                  }}
                />
              </div>
            ) : done ? (
              <div className={pw.body}>
                <h2 id={titleId} className="sr-only">
                  {t('done.title')}
                </h2>
                <PurchaseDone purchase={purchase} onDone={onClose} />
              </div>
            ) : (
              <div className={pw.body}>
                <span className={pw.kicker}>
                  <Seal size={14} />
                  {moment.kind === 'last' ? t('trialEnd.kickerLast') : t('trialEnd.kickerEnded')}
                </span>
                <h2 id={titleId} className={pw.title}>
                  {title}
                </h2>
                <p className={pw.lead}>{lead}</p>
                {rows.length > 0 && (
                  <section className={styles.did} aria-labelledby={`${titleId}-did`}>
                    <h3 id={`${titleId}-did`} className={styles.didTitle}>
                      {t('plan.facts.title')}
                    </h3>
                    <ul className={styles.rows}>
                      {rows.map((row) => (
                        <li key={row.label}>
                          <span className={cx(pw.perkIcon, pw[`tint_${row.tint}`])} aria-hidden="true">
                            <Icon name={row.icon} size={16} />
                          </span>
                          <span className={styles.rowLabel}>{row.label}</span>
                          <b className={styles.rowCount}>{row.count}</b>
                        </li>
                      ))}
                    </ul>
                  </section>
                )}
                {ended && <EndedLine offer={offer} />}
                {!ended && offer !== undefined && isNight(offer.creative) && canBuyHere(state) && (
                  <NightLine
                    offer={offer}
                    onEnded={() => {
                      setEnded(true);
                      void refresh();
                    }}
                  />
                )}
                {purchase.notice !== null && (
                  <p className={pw.notice} role="status">
                    {purchase.notice}
                  </p>
                )}
                <PlanPicker
                  model={model}
                  legend={moment.kind === 'last' ? t('pick.legend') : t('pick.legendGet')}
                  legendHidden
                  disabled={purchase.busy !== null}
                  countdown={{
                    surface: 'opened',
                    label: countdownLabel(badge),
                    liveSecondsFromHours: look?.liveSecondsFromHours ?? LIVE_HOURS,
                    style: look?.countdownStyle ?? 'auto',
                    pips: true,
                    onEnded: () => {
                      setEnded(true);
                      void refresh();
                    },
                  }}
                />
                {invite !== undefined && (
                  <section className={styles.invite} aria-labelledby={`${titleId}-invite`}>
                    <span className={cx(pw.perkIcon, pw.tint_g)} aria-hidden="true">
                      <Icon name="gift" size={18} />
                    </span>
                    <div className={styles.inviteText}>
                      <h3 id={`${titleId}-invite`} className={styles.inviteTitle}>
                        {t('trialEnd.inviteTitle')}
                      </h3>
                      <p className={styles.inviteLine}>
                        {invite.friends === undefined
                          ? t('trialEnd.inviteLine', { days: invite.days })
                          : `${t('trialEnd.invitePitch', { count: invite.friends, days: pitchDays(invite) })} ${t(
                              'trialEnd.inviteEach',
                              { days: invite.days },
                            )}`}
                      </p>
                      <Link
                        to={`${settingsPath('invite')}?via=plan`}
                        className={styles.inviteAction}
                        onClick={onClose}
                      >
                        {t('trialEnd.inviteAction', { count: invite.friends ?? 1 })}
                        <Icon name="chevronRight" size={16} weight={2} />
                      </Link>
                    </div>
                  </section>
                )}
                <LegalRow
                  store={model.store}
                  restore={onIOS() ? restore : undefined}
                  disabled={purchase.busy !== null}
                />
              </div>
            )}
          </div>
          {!done && !asking && (
            <div className={pw.bar}>
              <BuyButton
                model={model}
                trial={moment.kind === 'last'}
                busy={purchase.busy !== null}
                disabled={purchase.busy !== null}
                describedBy={`${trustId} ${legalId}`}
                onBuy={(choice) => {
                  sendPaywallEvent('offer_paywall', 'checkout_started');
                  if (offer !== undefined) sendOfferEvent(offer.id, 'opened', SURFACE);
                  purchase.buy(choice.id, choice.offer, { billed: choice.billed, renewal: choice.renewal });
                }}
              />
              {purchase.error !== null && (
                <p className={kp.trust} role="alert">
                  {purchase.error}
                </p>
              )}
              <BuyFoot
                model={model}
                trial={moment.kind === 'last'}
                ids={{ trust: trustId, legal: legalId }}
              />
              <button
                type="button"
                className={styles.free}
                onClick={() => {
                  leave.current();
                }}
              >
                {t('trialEnd.continueFree')}
              </button>
            </div>
          )}
        </div>
      </div>
    </div>,
    document.body,
  );
}

/** The Black Friday line on the night card, above the plans (uiux spec 2026-10-24 §3.3). */
function NightLine({ offer, onEnded }: { offer: Offer; onEnded: () => void }): React.JSX.Element | null {
  const words = useOfferWords(offer);
  if (words === undefined) return null;
  const badge = offerBadgeKind(offer);
  const [before, after] = aroundAmount((amount) => t('night.trialEnd', { amount }));
  return (
    <div className={styles.night} style={nightStyle(offer.creative)}>
      {badge !== undefined && <span className={styles.nightPill}>{badgeWords(badge, offer)}</span>}
      <p className={styles.nightLine}>
        {before}
        <bdi dir="ltr">{words.first}</bdi>
        {after}
      </p>
      <NightClosing offer={offer} opened className={styles.nightWhen} onEnded={onEnded} />
    </div>
  );
}

/**
 * Live seconds in the offer's last day when its campaign says nothing
 * (the sales plan: h:m:s in the last 24 hours), the most `countdown.ts`
 * allows. The campaign's own `liveSecondsFromHours` wins when it has one.
 */
const LIVE_HOURS = 24;
